def upgrade() -> None:
    op.execute("ALTER TABLE discovery.cities ADD COLUMN boundary_source text")
    connection = op.get_bind()
    for slug, (source, geometry) in BOUNDARIES.items():
        connection.execute(
            text(
                """
            UPDATE discovery.cities
            SET boundary = ST_Multi(ST_SetSRID(ST_GeomFromGeoJSON(:geometry), 4326))::geography,
                boundary_source = :source,
                updated_at = now()
            WHERE slug = :slug
            """,
            ),
            {"geometry": geometry, "source": source, "slug": slug},
        )
    op.execute(
        "ALTER TABLE discovery.cities ALTER COLUMN boundary SET NOT NULL"
    )
    op.execute(
        "ALTER TABLE discovery.cities ALTER COLUMN boundary_source SET NOT NULL"
    )


def downgrade() -> None:
    op.execute("ALTER TABLE discovery.cities ALTER COLUMN boundary DROP NOT NULL")
    op.execute("UPDATE discovery.cities SET boundary = NULL")
    op.execute("ALTER TABLE discovery.cities DROP COLUMN boundary_source")
